afterExample:
import org.eclipse.jface.text.IDocument;
import org.eclipse.jface.text.IRegion;
import org.eclipse.jface.text.BadLocationException;

public class Example {
    void calculateSpaces(IDocument document, IRegion match) throws BadLocationException {
        // Correct usage: first get the line number for the offset, then use it
        int spaces = match.getOffset() + match.getLength() - document.getLineOffset(document.getLineOfOffset(match.getOffset()));
        System.out.println(spaces);
    }
}

