import org.eclipse.jface.text.IDocument;
import org.eclipse.jface.text.IRegion;
import org.eclipse.jface.text.BadLocationException;

public class Example {
    void calculateSpaces(IDocument document, IRegion match, int lineNumber) throws BadLocationException {
        // Correct usage with an explicit line number, should not be matched
        int spaces1 = document.getLineOffset(lineNumber);
        System.out.println(spaces1);

        // Correct usage with a literal line number, should not be matched
        int spaces2 = document.getLineOffset(5);
        System.out.println(spaces2);

        // Call to a different method, should not be matched
        // Assuming 'document' has a method 'someOtherMethodTakingOffset'
        int spaces3 = document.getLineOfOffset(match.getOffset());
        System.out.println(spaces3);
    }
}
